/// Where a lease is in its lifecycle.
/// </summary>
[JsonConverter(typeof(StrictEnumConverter<LeaseState>))]
public enum LeaseState
{
    /// <summary>
    /// Waiting for resources.
    /// </summary>
    [JsonStringEnumMemberName("queued")]
    Queued,

    /// <summary>
    /// Granted; its reservation counts against the machine.
    /// </summary>
    [JsonStringEnumMemberName("active")]
    Active,

    /// <summary>
    /// Released by its holder.
    /// </summary>
    [JsonStringEnumMemberName("released")]
    Released,

    /// <summary>
    /// Ended by the daemon because the heartbeat stopped or the holder died.
    /// </summary>
    [JsonStringEnumMemberName("expired")]
    Expired,
}

/// <summary>
/// Machine meters with the share that leases reserve.
/// </summary>
public sealed record Meters
{
    /// <summary>
    /// Processor load.
    /// </summary>
    public required CpuMeter Cpu { get; init; }

    /// <summary>
    /// Every fixed drive, by drive letter on Windows and by mount point elsewhere.
    /// </summary>
    public required IReadOnlyList<DriveUsage> Drives { get; init; }

    /// <summary>
    /// Every GPU adapter.
    /// </summary>
    public required IReadOnlyList<GpuMeter> Gpus { get; init; }

    /// <summary>
    /// Percentage of each resource that leases never take, from <c>admission.headroom_pct</c>.
    /// </summary>
    public required float HeadroomPct { get; init; }

    /// <summary>
    /// Physical memory.
    /// </summary>
    public required RamMeter Ram { get; init; }
}

/// <summary>
/// Load from processes outside the holder's session while a benchmark lease was active.
///
/// CPU is the summed per-process load of every other session and of processes outside all
/// sessions. Kernel and interrupt time belongs to no process, so it is not counted: it would
/// otherwise charge the benchmark's own system time as noise.
/// </summary>
public sealed record NoiseReport
{
    /// <summary>
    /// Average CPU load of other processes, as a percentage of all logical processors.
    /// </summary>
    public required float AvgCpuPct { get; init; }

    /// <summary>
    /// Average GPU engine load of other processes, as a percentage of one adapter.
    /// </summary>
    public required float AvgGpuPct { get; init; }

    /// <summary>
    /// Peak CPU load of other processes.
    /// </summary>
    public required float PeakCpuPct { get; init; }

    /// <summary>
    /// Peak GPU engine load of other processes.
    /// </summary>
    public required float PeakGpuPct { get; init; }

    /// <summary>
    /// Whether the machine met the quiet limits when the lease was granted. <c>false</c> means it
    /// was granted anyway after the longest quiet wait.
    /// </summary>
    public required bool QuietAtStart { get; init; }
}

/// <summary>
/// A kill or removal that Claude must hear about once.
/// </summary>
public sealed record Notice
{
    /// <summary>
    /// What the user did: <c>EndCause::Killed</c> or <c>EndCause::Removed</c>.
    /// </summary>
    public required EndCause Cause { get; init; }

    /// <summary>
    /// The lease's label, usually the command.
    /// </summary>
    public required string Command { get; init; }

    /// <summary>
    /// When a hook or tool result told the session, or <c>null</c> while it has not been told.
    /// </summary>
    public long? DeliveredAtMs { get; init; }

    /// <summary>
    /// When the lease ended, in milliseconds since the Unix epoch.
    /// </summary>
    public required long EndedAtMs { get; init; }

    /// <summary>
    /// Lease the notice is about. A lease ends once, so this also identifies the notice.
    /// </summary>
    public required long LeaseId { get; init; }

    /// <summary>
    /// Session to tell.
    /// </summary>
    public required string Session { get; init; }

    /// <summary>
    /// Claude Code's ID for the tool call the lease was bound to, or <c>null</c> when no hook
    /// reported one. A hook compares it with its own call to say "this command".
    /// </summary>
    public string? ToolUseId { get; init; }
}

/// <summary>
/// A switch that turns a numeric feature off by writing one value.
/// </summary>
public sealed record OffSwitch
{
    /// <summary>
    /// The switch's help.
    /// </summary>
    public required string Help { get; init; }

    /// <summary>
    /// The switch's label, describing the on state.
    /// </summary>
    public required string Label { get; init; }

    /// <summary>
    /// The value written while the switch is off.
    /// </summary>
    public required double Value { get; init; }
}

/// <summary>
/// An operating system a panel runs on.
/// </summary>
[JsonConverter(typeof(StrictEnumConverter<Platform>))]
public enum Platform
{
    /// <summary>
    /// The Windows tray.
    /// </summary>
    [JsonStringEnumMemberName("windows")]
    Windows,

    /// <summary>
    /// The macOS menu bar app.
    /// </summary>
    [JsonStringEnumMemberName("macos")]
    Macos,

    /// <summary>
    /// The GNOME extension and the KDE widget.
    /// </summary>
    [JsonStringEnumMemberName("linux")]
    Linux,
}

/// <summary>
/// What a number counts.
/// </summary>
[JsonConverter(typeof(StrictEnumConverter<Quantity>))]
public enum Quantity
{
    /// <summary>
    /// A share from 0 to 100.
    /// </summary>
    [JsonStringEnumMemberName("percent")]
    Percent,

    /// <summary>
    /// A number of job runs.
    /// </summary>
    [JsonStringEnumMemberName("runs")]
    Runs,

    /// <summary>
    /// A number of days.
    /// </summary>
    [JsonStringEnumMemberName("days")]
    Days,

    /// <summary>
    /// A duration in seconds; panels may show it in minutes or hours.
    /// </summary>
    [JsonStringEnumMemberName("seconds")]
    Seconds,

    /// <summary>
    /// Logical cores; fractions are allowed.
    /// </summary>
    [JsonStringEnumMemberName("cores")]
    Cores,

    /// <summary>
    /// Memory in megabytes; panels may show it in gigabytes.
    /// </summary>
    [JsonStringEnumMemberName("megabytes")]
    Megabytes,

    /// <summary>
    /// A TCP port, shown without digit grouping.
    /// </summary>
    [JsonStringEnumMemberName("port")]
    Port,
}

/// <summary>
/// A queued lease and why it waits.
/// </summary>
public sealed record QueuedJob
{
    /// <summary>
    /// The lease.
    /// </summary>
    public required Lease Lease { get; init; }

    /// <summary>
    /// Place in the queue, starting at 1.
    /// </summary>
    public required uint Position { get; init; }

    /// <summary>
    /// Why it waits, the expected wait, and benchmark progress when it is a benchmark.
    /// </summary>
    public required Verdict Verdict { get; init; }
}

/// <summary>
/// Physical memory.
/// </summary>
public sealed record RamMeter
{
    /// <summary>
    /// Memory reserved by active leases.
    /// </summary>
    public required ulong ReservedMb { get; init; }

    /// <summary>
    /// Installed physical memory.
    /// </summary>
    public required ulong TotalMb { get; init; }

    /// <summary>
    /// Physical memory in use.
    /// </summary>
    public required ulong UsedMb { get; init; }
}

/// <summary>
/// A finished job.
/// </summary>
public sealed record RecentRun
{
    /// <summary>
    /// The lease's label, usually the command as it was run.
    /// </summary>
    public required string Command { get; init; }

    /// <summary>
    /// Working directory of the command.
    /// </summary>
    public required string Cwd { get; init; }

    /// <summary>
    /// Profile the lease reserved.
    /// </summary>
    public required JobProfile Declared { get; init; }

    /// <summary>
    /// Why it ended; <c>null</c> for runs recorded before causes were.
    /// </summary>
    public EndCause? EndCause { get; init; }

    /// <summary>
    /// End of the run, in milliseconds since the Unix epoch.
    /// </summary>
    public required long EndedAtMs { get; init; }

    /// <summary>
    /// Lease the job ran under, if the lease is still stored.
    /// </summary>
    public long? LeaseId { get; init; }

    /// <summary>
    /// Background load during the run; present only for benchmark leases.
    /// </summary>
    public NoiseReport? Noise { get; init; }

    /// <summary>
    /// Session that ran it; <c>null</c> for runs recorded before sessions were.
    /// </summary>
    public string? Session { get; init; }

    /// <summary>
    /// Start of the run, in milliseconds since the Unix epoch.
    /// </summary>
    public required long StartedAtMs { get; init; }

    /// <summary>
    /// Median, p90 and max of the job's runs, as <c>allot history</c> shows them; <c>null</c> when no run
    /// of the job counts, and from older daemons.
    /// </summary>
    public RunStats? Stats { get; init; }
}

/// <summary>
/// A switch another setting depends on.
/// </summary>
public sealed record Requirement
{
    /// <summary>
    /// The switch's key.
    /// </summary>
    public required string Key { get; init; }

    /// <summary>
    /// Shown under the disabled setting while the switch is off.
    /// </summary>
    public required string Note { get; init; }
}

/// <summary>
/// Resources used by a process or a group of processes, in the units of <c>JobProfile</c>.
/// </summary>
public sealed record ResourceUsage
{
    /// <summary>
    /// CPU load in logical cores, for example <c>2.5</c> for two and a half busy cores.
    /// </summary>
    public required float Cores { get; init; }

    /// <summary>
    /// GPU engine load as a percentage of one adapter.
    /// </summary>
    public required float GpuPct { get; init; }

    /// <summary>
    /// Resident memory; on macOS the physical footprint, as Activity Monitor shows it.
    /// </summary>
    public required ulong RamMb { get; init; }

    /// <summary>
    /// Dedicated video memory.
    /// </summary>
    public required ulong VramMb { get; init; }
}

/// <summary>
/// The name field of a row the user adds or renames.
/// </summary>
public sealed record RowName
{
    /// <summary>
    /// The field's help.
    /// </summary>
    public required string Help { get; init; }

    /// <summary>
    /// The field's label.
    /// </summary>
    public required string Label { get; init; }

    /// <summary>
    /// A regular expression the whole name must match. A name must also differ from every
    /// other row's and from every class's.
    /// </summary>
    public required string Pattern { get; init; }
}

/// <summary>
/// Median, p90 and max of what a job's runs used: the newest runs that neither overlapped
/// another lease of their session nor were killed, at most as many as an estimate reads.
/// Cores and GPU load are each run's average while its session was busy, RAM and VRAM its
/// peak, and <c>est_secs</c> its run time.
/// </summary>
public sealed record RunStats
{
    /// <summary>
    /// Highest of each value.
    /// </summary>
    public required JobProfile Max { get; init; }

    /// <summary>
    /// Nearest-rank median of each value.
    /// </summary>
    public required JobProfile Median { get; init; }

    /// <summary>
    /// Nearest-rank 90th percentile of each value, which estimates raise and lower to.
    /// </summary>
    [JsonPropertyName("p90")]
    public required JobProfile P90 { get; init; }

    /// <summary>
    /// Runs the statistics come from.
    /// </summary>
    public required uint Runs { get; init; }
}

/// <summary>
/// How a setting is edited.
/// </summary>
[JsonPolymorphic(TypeDiscriminatorPropertyName = "kind")]
[JsonDerivedType(typeof(SettingControl.Switch), "switch")]
[JsonDerivedType(typeof(SettingControl.Number), "number")]
[JsonDerivedType(typeof(SettingControl.Text), "text")]
[JsonDerivedType(typeof(SettingControl.Choice), "choice")]
[JsonDerivedType(typeof(SettingControl.StringList), "string_list")]
[JsonDerivedType(typeof(SettingControl.SizeTable), "size_table")]
[JsonDerivedType(typeof(SettingControl.RuleList), "rule_list")]
public abstract record SettingControl
{
    /// <summary>
    /// On or off.
    /// </summary>
    public sealed record Switch : SettingControl
    {
        /// <summary>
        /// The value while the key is not in the file.
        /// </summary>
        public required bool Default { get; init; }
    }

    /// <summary>
    /// A number in a unit, written to the file in that unit.
    /// </summary>
    public sealed record Number : SettingControl
    {
        /// <summary>
        /// How the value is worked out while the key is left out, when it may be, shown
        /// beside an Automatic choice.
        /// </summary>
        public string? Automatic { get; init; }

        /// <summary>
        /// The value while the key is not in the file. In a table's fields, the value a new
        /// row starts with, or <c>null</c> when a new row must give one or <c>automatic</c> applies.
        /// </summary>
        public double? Default { get; init; }

        /// <summary>
        /// Whether only whole numbers are allowed.
        /// </summary>
        public required bool Integer { get; init; }

        /// <summary>
        /// The largest value allowed, if any besides <c>max_key</c>.
        /// </summary>
        public Bound? Max { get; init; }

        /// <summary>
        /// A setting this value must be at most, by key; in a table, a field of the same row.
        /// </summary>
        public string? MaxKey { get; init; }

        /// <summary>
        /// The smallest value allowed, if any besides <c>min_key</c>.
        /// </summary>
        public Bound? Min { get; init; }

        /// <summary>
        /// A setting this value must be at least, by key; in a table, a field of the same row.
        /// </summary>
        public string? MinKey { get; init; }

        /// <summary>
        /// A switch in front of the number, when one value turns the feature off.
        /// </summary>
        public OffSwitch? Off { get; init; }

        /// <summary>
        /// What the number counts, which picks its unit and display.
        /// </summary>
        public required Quantity Quantity { get; init; }
    }

    /// <summary>
    /// A line of text, never blank.
    /// </summary>
    public sealed record Text : SettingControl
    {
        /// <summary>
        /// A regular expression the whole text must match, if any.
        /// </summary>
        public string? Pattern { get; init; }
    }

    /// <summary>
    /// One of a fixed set of values.
    /// </summary>
    public sealed record Choice : SettingControl
    {
        /// <summary>
        /// The value a new item starts with, or <c>null</c> when one must be picked.
        /// </summary>
        public string? Default { get; init; }

        /// <summary>
        /// The values in display order.
        /// </summary>
        public required IReadOnlyList<ChoiceOption> Options { get; init; }
    }

    /// <summary>
    /// A list of strings without blank entries; a list in the file replaces the default list.
    /// </summary>
    public sealed record StringList : SettingControl
    {
        /// <summary>
        /// The list while the key is not in the file.
        /// </summary>
        public required IReadOnlyList<string> Default { get; init; }
    }

    /// <summary>
    /// Named rows of sizes, such as <c>[classes.cpu_heavy]</c>, edited one row at a time. A row
    /// in the file changes only the fields it names.
    /// </summary>
    public sealed record SizeTable : SettingControl
    {
        /// <summary>
        /// The fields of every row.
        /// </summary>
        public required IReadOnlyList<SettingSpec> Fields { get; init; }

        /// <summary>
        /// How a row added by the user is named, or <c>null</c> when rows cannot be added,
        /// renamed or deleted.
        /// </summary>
        public RowName? NewRowName { get; init; }

        /// <summary>
        /// The built-in rows with their defaults, which always exist.
        /// </summary>
        public required IReadOnlyList<SizeRowSpec> Rows { get; init; }
    }

    /// <summary>
    /// An ordered list of heavy-command rules, always written whole. A list in the file, even
    /// an empty one, replaces the default list; removing the key brings the default back.
    /// </summary>
    public sealed record RuleList : SettingControl
    {
        /// <summary>
        /// The list while the key is not in the file.
        /// </summary>
        public required IReadOnlyList<HeavyRule> Default { get; init; }

        /// <summary>
        /// The fields of every rule.
        /// </summary>
        public required IReadOnlyList<SettingSpec> Fields { get; init; }
    }
}

/// <summary>
/// One setting: a key of <c>config.toml</c>, or a field of a table row or rule.
/// </summary>
public sealed record SettingSpec
{
    /// <summary>
    /// Whether the setting is rarely changed and shows last on its page, under Advanced.
    /// </summary>
    public required bool Advanced { get; init; }

    /// <summary>
    /// How the value is edited, with its default and range.
    /// </summary>
    public required SettingControl Control { get; init; }

    /// <summary>
    /// One or two plain sentences. Panels show the key after them.
    /// </summary>
    public required string Help { get; init; }

    /// <summary>
    /// The TOML key: a dotted path such as <c>admission.headroom_pct</c> for a setting on a page,
    /// or the key inside a row, such as <c>cores</c>, for a field of a table or rule.
    /// </summary>
    public required string Key { get; init; }

    /// <summary>
    /// A noun phrase in sentence case; a switch's label describes the on state.
    /// </summary>
    public required string Label { get; init; }

    /// <summary>
    /// Whether a change takes effect only once allotd restarts.
    /// </summary>
    public required bool NeedsRestart { get; init; }

    /// <summary>
    /// The operating systems whose panels show the setting; empty means every one.
    /// </summary>
    public required IReadOnlyList<Platform> Platforms { get; init; }

    /// <summary>
    /// A switch that must be on for this setting to act; panels disable it while it is off.
    /// </summary>
    public Requirement? Requires { get; init; }
}

/// <summary>
/// A titled group of settings on a page.
/// </summary>
public sealed record SettingsGroupSpec
{
    /// <summary>
    /// Stable identifier, unique on its page, such as <c>learn</c>.
    /// </summary>
    public required string Id { get; init; }

    /// <summary>
    /// The group's title.
    /// </summary>
    public required string Label { get; init; }

    /// <summary>
    /// The settings, in group order.
    /// </summary>
    public required IReadOnlyList<SettingSpec> Settings { get; init; }
}

/// <summary>
/// A page of the Settings window.
/// </summary>
public sealed record SettingsPageSpec
{
    /// <summary>
    /// The groups, in page order.
    /// </summary>
    public required IReadOnlyList<SettingsGroupSpec> Groups { get; init; }

    /// <summary>
    /// Stable identifier, such as <c>admission</c>.
    /// </summary>
    public required string Id { get; init; }

    /// <summary>
    /// A sentence under the title, if the page has one.
    /// </summary>
    public string? Intro { get; init; }

    /// <summary>
    /// The page's title.
    /// </summary>
    public required string Label { get; init; }
}

/// <summary>
/// A built-in row of a size table.
/// </summary>
public sealed record SizeRowSpec
{
    /// <summary>
    /// The row's values while the file does not change them.
    /// </summary>
    public required JobProfile Default { get; init; }

    /// <summary>
    /// The row's minimum cores while the file names none; <c>null</c> follows the field's
    /// automatic rule.
    /// </summary>
    public float? DefaultMinCores { get; init; }

    /// <summary>
    /// The row as the panel shows it.
    /// </summary>
    public required string Label { get; init; }

    /// <summary>
    /// The row's key in the file, such as <c>cpu_heavy</c>.
    /// </summary>
    public required string Name { get; init; }
}

/// <summary>
/// Where the stop came from.
/// </summary>
[JsonConverter(typeof(StrictEnumConverter<StoppedBy>))]
public enum StoppedBy
{
    /// <summary>
    /// <c>allot daemon stop</c>.
    /// </summary>
    [JsonStringEnumMemberName("cli")]
    Cli,

    /// <summary>
    /// Stop service in a panel.
    /// </summary>
    [JsonStringEnumMemberName("panel")]
    Panel,
}

/// <summary>
/// One registered Claude session.
/// </summary>
public sealed record UiSession
{
    /// <summary>
    /// Working directory of the session's most recent lease, which names its project; <c>null</c>
    /// when no lease gave one.
    /// </summary>
    public string? Cwd { get; init; }

    /// <summary>
    /// Session ID.
    /// </summary>
    public required string Session { get; init; }

    /// <summary>
    /// Live usage of the session's whole process subtree.
    /// </summary>
    public required ResourceUsage Usage { get; init; }
}

/// <summary>
/// A process in a killed tree that is still running.
/// </summary>
public sealed record UnkilledProcess
{
    /// <summary>
    /// Executable name, for example <c>claude.exe</c>.
    /// </summary>
    public required string Name { get; init; }

    /// <summary>
    /// Process ID.
    /// </summary>
    public required uint Pid { get; init; }

    /// <summary>
    /// Why it is still running.
    /// </summary>
    public required string Reason { get; init; }
}

/// <summary>
/// The admission engine's answer. Response of <c>POST /can-fit</c>.
/// </summary>
public sealed record Verdict
{
    /// <summary>
    /// Where a benchmark at the head of the queue stands; <c>null</c> for other requests.
    /// </summary>
    public BenchmarkProgress? Benchmark { get; init; }

    /// <summary>
    /// Whether the job could start now.
    /// </summary>
    public required bool Fits { get; init; }

    /// <summary>
    /// Human-readable explanations, one per limiting or notable factor.
    /// </summary>
    public required IReadOnlyList<string> Reasons { get; init; }

    /// <summary>
    /// Expected wait before the job fits, when the daemon can estimate it.
    /// </summary>
    public ulong? WaitEstimateSecs { get; init; }
}

/// <summary>
/// Decodes an enum from its serde name only, never from a number.
/// </summary>
public sealed class StrictEnumConverter<TEnum> : JsonStringEnumConverter<TEnum>
    where TEnum : struct, System.Enum
{
    /// <summary>
    /// Creates the converter with integer values turned off.
    /// </summary>
    public StrictEnumConverter()
        : base(namingPolicy: null, allowIntegerValues: false)
    {
    }
}

/// <summary>
/// System.Text.Json metadata for the contract types, with the options their serde shapes need.
/// </summary>
[JsonSourceGenerationOptions(
    PropertyNamingPolicy = JsonKnownNamingPolicy.SnakeCaseLower,
    AllowOutOfOrderMetadataProperties = true,
    RespectNullableAnnotations = true)]
[JsonSerializable(typeof(UiState))]
[JsonSerializable(typeof(KillResponse))]
[JsonSerializable(typeof(RemoveResponse))]
[JsonSerializable(typeof(SettingsSpec))]
[JsonSerializable(typeof(StopRecord))]
public sealed partial class ContractJsonContext : JsonSerializerContext
{
}
